-- RedAnt update 3: UK lead-generation copy rewrite, real URLs, industry + city pages.
-- Safe to run more than once. Run AFTER schema.sql, data.sql and update-2.sql.

-- ---------- structure ----------
ALTER TABLE industries ADD COLUMN IF NOT EXISTS h1 TEXT;
ALTER TABLE industries ADD COLUMN IF NOT EXISTS meta_title TEXT;
ALTER TABLE industries ADD COLUMN IF NOT EXISTS meta_desc TEXT;
ALTER TABLE industries ADD COLUMN IF NOT EXISTS faqs_json TEXT;
ALTER TABLE services   ADD COLUMN IF NOT EXISTS path_card_text TEXT;

CREATE TABLE IF NOT EXISTS locations (
  id SERIAL PRIMARY KEY,
  slug TEXT UNIQUE,
  city TEXT,
  h1 TEXT,
  intro TEXT,
  local_example TEXT,
  meta_title TEXT,
  meta_desc TEXT,
  order_num INTEGER DEFAULT 0
);
ALTER TABLE locations ENABLE ROW LEVEL SECURITY;

