UPDATE landing_pages SET headline='*48-hour website refresh* for UK small businesses: £199', subtext='Your website has the right content but looks dated, loads slowly or breaks on phones. We rebuild the design, speed and mobile layout in two days, keeping your words, your brand and your page addresses so your Google rankings are protected.', cta_text='Claim my £199 refresh', meta_title='48-Hour Website Refresh UK | £199 Fixed | RedAnt', meta_desc='Website refresh for UK small businesses. Modern, mobile-first and faster in 48 hours for a fixed £199. Keep your content and brand.', status='published' WHERE slug='website-refresh';
UPDATE landing_pages SET headline='*Affordable website design* for UK small businesses', subtext='A custom website built around how your customers search, compare and choose. Designed to look credible, load fast and make it easy to call or book.', cta_text='Book a free discovery call', meta_title='Affordable Website Design UK | From £499 | RedAnt', meta_desc='Custom 5 or 10-page websites for UK small businesses from £499. Mobile-first, fast, SEO-ready and fully owned by you. Fixed prices.', status='published' WHERE slug='web-design';
UPDATE landing_pages SET headline='*WordPress web designer* for UK businesses', subtext='A WordPress and Elementor site you can edit yourself: change prices, add photos and publish news without calling a developer. Fast, secure and set up properly from day one.', cta_text='Get a WordPress quote', meta_title='WordPress Web Designer UK | Elementor Sites | RedAnt', meta_desc='WordPress and Elementor websites you can edit yourself, built fast and secure for UK small businesses. Get a quote today.', status='published' WHERE slug='wordpress-developer';
UPDATE landing_pages SET headline='*Local SEO* for UK small businesses: get found in your town', subtext='When someone searches "plumber near me" or "physio in Leeds", you want to be in the top three on Google Maps. We optimise your Google Business Profile and your website so local customers find you first.', cta_text='Get my free local SEO check', meta_title='Local SEO UK | Google Maps Ranking | RedAnt', meta_desc='Local SEO for UK small businesses: Google Business Profile, local keywords and location pages so nearby customers find you first.', status='published' WHERE slug='local-seo';
UPDATE landing_pages SET headline='*Website maintenance plans* for UK businesses from £29 a month', subtext='Updates, backups, security and hosting handled for you, so your website never goes down, gets hacked or falls out of date.', cta_text='Start a care plan', meta_title='Website Maintenance Plans UK | £29/mo | RedAnt', meta_desc='Website care plans from £29 a month: UK-based hosting, daily backups, SSL, updates and security monitoring for small businesses.', status='published' WHERE slug='website-care-plans';
UPDATE landing_pages SET headline='*Facebook and Instagram ad graphics* for UK businesses from £99', subtext='Scroll-stopping ad creatives, logo refinements and social templates that match your website and make your ads work harder.', cta_text='Order a graphics pack', meta_title='Facebook & Instagram Ad Graphics UK | RedAnt', meta_desc='Facebook and Instagram ad graphics, logo refinements and social templates for UK businesses from £99.', status='published' WHERE slug='social-media-graphics';

