INSERT INTO services (slug,name,icon,price_from,short_desc,path_card_text,order_num) VALUES ('social-media-graphics','Ad & Social Graphics','🖼️',99,'Facebook and Instagram ad creatives, logo refinements and social templates.','I need ads and social graphics. Facebook and Instagram creatives from £99.',6) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, icon=EXCLUDED.icon, price_from=EXCLUDED.price_from, short_desc=EXCLUDED.short_desc, path_card_text=EXCLUDED.path_card_text, order_num=EXCLUDED.order_num;

