DELETE FROM industries;
INSERT INTO industries (slug,name,h1,intro,problems_json,cta_text,faqs_json,meta_title,meta_desc,order_num) VALUES ('clinics','Clinics & Healthcare','Website design for UK clinics and healthcare practices','Patients choose a clinic they trust within seconds. We build calm, accessible sites with online booking, clear treatments and fees, and local SEO so new patients find you.','["Patients cannot find the booking link on a phone", "Treatments and prices are hard to find", "Pages load slowly, so anxious patients leave"]','Get a free review of your clinic website','[{"q": "Can you add online booking?", "a": "Yes. We can add booking and enquiry forms, or link to the booking system you already use. We do not give clinical or regulatory advice, so please check your own professional body''s rules on advertising."}, {"q": "How much does a website for a clinic cost?", "a": "A 48-hour refresh of an existing site is £199. A new 5-page site is £499 and a 10-page site is £899. All prices are fixed, so you know the cost before we start."}, {"q": "Can I update the website myself afterwards?", "a": "Yes. On WordPress and Elementor builds you can edit text, images and prices yourself, and we give you a short training video. You own your site and code once you''ve paid in full."}]','Web Design for Clinics UK | RedAnt','Website design for UK clinics and healthcare practices: accessible, mobile-friendly sites with clear treatments, fees and booking.',1);
INSERT INTO industries (slug,name,h1,intro,problems_json,cta_text,faqs_json,meta_title,meta_desc,order_num) VALUES ('trades','Trades & Construction','Websites for UK tradespeople and builders','Win more local jobs with a site that loads fast on a phone, shows your best work and puts a Call Now button under every thumb.','["No clear Call Now button on mobile", "Photos of past work are missing or slow to load", "The site does not show the towns you cover"]','Get a free review of your trade website','[{"q": "Will customers be able to call me straight from the site?", "a": "Yes. Every page gets a tap-to-call button and a short enquiry form that emails you."}, {"q": "How much does a website for a tradesperson cost?", "a": "A 48-hour refresh of an existing site is £199. A new 5-page site is £499 and a 10-page site is £899. All prices are fixed, so you know the cost before we start."}, {"q": "Can I update the website myself afterwards?", "a": "Yes. On WordPress and Elementor builds you can edit text, images and prices yourself, and we give you a short training video. You own your site and code once you''ve paid in full."}]','Web Design for Trades UK | RedAnt','Websites for UK tradespeople and builders that load fast on mobile, show your work and make it easy for customers to call.',2);
INSERT INTO industries (slug,name,h1,intro,problems_json,cta_text,faqs_json,meta_title,meta_desc,order_num) VALUES ('coaches','Coaches & Wellbeing','Website design for coaches, therapists and wellbeing brands','A warm, professional site with booking, email sign-up and testimonials that turns curious visitors into clients.','["It is unclear what you offer and who it is for", "No easy way to book a call or join a mailing list", "No testimonials or proof that builds trust"]','Get a free review of your coaching website','[{"q": "Can you add a booking calendar and email sign-up?", "a": "Yes. We can connect a booking tool and a newsletter sign-up such as Mailchimp, so visitors can book or subscribe from any page."}, {"q": "How much does a website for a coach or therapist cost?", "a": "A 48-hour refresh of an existing site is £199. A new 5-page site is £499 and a 10-page site is £899. All prices are fixed, so you know the cost before we start."}, {"q": "Can I update the website myself afterwards?", "a": "Yes. On WordPress and Elementor builds you can edit text, images and prices yourself, and we give you a short training video. You own your site and code once you''ve paid in full."}]','Web Design for Coaches UK | RedAnt','Website design for coaches, therapists and wellbeing brands with booking, email sign-up and testimonials that win clients.',3);
INSERT INTO industries (slug,name,h1,intro,problems_json,cta_text,faqs_json,meta_title,meta_desc,order_num) VALUES ('pubs','Pubs & Hospitality','Websites for UK pubs, cafes and restaurants','Show your menu, events and opening hours clearly and take bookings, with Google Maps visibility that fills tables.','["Menus are PDFs that are hard to read on a phone", "Opening hours and events are out of date", "No easy way to book a table"]','Get a free review of your venue website','[{"q": "Can the menu and opening hours be easy to update?", "a": "Yes. On WordPress builds you can edit your menu, events and opening hours yourself, and we help set up your Google Business Profile so hours match everywhere."}, {"q": "How much does a website for a pub or restaurant cost?", "a": "A 48-hour refresh of an existing site is £199. A new 5-page site is £499 and a 10-page site is £899. All prices are fixed, so you know the cost before we start."}, {"q": "Can I update the website myself afterwards?", "a": "Yes. On WordPress and Elementor builds you can edit text, images and prices yourself, and we give you a short training video. You own your site and code once you''ve paid in full."}]','Web Design for Pubs UK | RedAnt','Websites for UK pubs, cafes and restaurants: clear menus, events, opening hours and bookings, with Google Maps visibility.',4);

