INSERT INTO locations (slug,city,h1,intro,local_example,meta_title,meta_desc,order_num) VALUES ('web-design-london','London','Web designer in London: fixed prices from £199','London is one of the most competitive places in the UK to be found online. Customers compare several businesses before they call, so a slow or dated site quietly costs you enquiries. We help London sole traders, clinics, studios and local services get a fast, clear, mobile-friendly website at a fixed price.',NULL,'Web Designer in London | Fixed Prices | RedAnt','Web design for London small businesses. Fast, mobile-friendly websites from £199 with fixed prices and direct WhatsApp support.',1);
INSERT INTO locations (slug,city,h1,intro,local_example,meta_title,meta_desc,order_num) VALUES ('web-design-manchester','Manchester','Web designer in Manchester: fixed prices from £199','From independent shops in the city centre to trades and clinics across Salford, Stockport and Trafford, Greater Manchester businesses compete for the same local searches. We build fast, mobile-first websites that make it easy for nearby customers to call, book or enquire.',NULL,'Web Designer in Manchester | Fixed Prices | RedAnt','Web design for Manchester small businesses. Fast, mobile-friendly websites from £199 with fixed prices and direct WhatsApp support.',2);
INSERT INTO locations (slug,city,h1,intro,local_example,meta_title,meta_desc,order_num) VALUES ('web-design-leeds','Leeds','Web designer in Leeds: fixed prices from £199','Leeds and West Yorkshire businesses, from professional services in the city centre to trades covering Headingley, Chapel Allerton and beyond, win work when customers can find them quickly on a phone. We build clear, fast sites and set up local SEO so you show up in your area.',NULL,'Web Designer in Leeds | Fixed Prices | RedAnt','Web design for Leeds small businesses. Fast, mobile-friendly websites from £199 with fixed prices and direct WhatsApp support.',3);
INSERT INTO locations (slug,city,h1,intro,local_example,meta_title,meta_desc,order_num) VALUES ('web-design-birmingham','Birmingham','Web designer in Birmingham: fixed prices from £199','Birmingham and the wider West Midlands cover everything from studios and makers to trades serving Solihull, Edgbaston and Sutton Coldfield. We help local businesses replace slow, dated sites with fast, mobile-friendly ones that turn searches into enquiries.',NULL,'Web Designer in Birmingham | Fixed Prices | RedAnt','Web design for Birmingham small businesses. Fast, mobile-friendly websites from £199 with fixed prices and direct WhatsApp support.',4);
INSERT INTO locations (slug,city,h1,intro,local_example,meta_title,meta_desc,order_num) VALUES ('web-design-liverpool','Liverpool','Web designer in Liverpool: fixed prices from £199','Liverpool and Merseyside have a strong community of independent venues, wellbeing studios, clinics and trades, including across the Wirral and Sefton. We build fast, easy-to-use websites and local SEO that help nearby customers choose you.',NULL,'Web Designer in Liverpool | Fixed Prices | RedAnt','Web design for Liverpool small businesses. Fast, mobile-friendly websites from £199 with fixed prices and direct WhatsApp support.',5);

-- ---------- FAQs ----------
DELETE FROM faqs;
INSERT INTO faqs (question,answer,category,order_num) VALUES ('How much does a small business website cost in the UK?','Typical UK agencies charge £2,000 to £5,000 or more. At RedAnt, a website refresh is £199, a 5-page site is £499 and a 10-page site is £899, all fixed prices.','General',1);
INSERT INTO faqs (question,answer,category,order_num) VALUES ('Can you really refresh a website in 48 hours?','Yes, when you have an existing site and content. We reuse your text and brand, and update design, mobile layout and speed. Larger rebuilds take 2 to 4 weeks.','General',2);
INSERT INTO faqs (question,answer,category,order_num) VALUES ('Do I own my website?','Yes. Once you''ve paid in full, the site and code are 100% yours.','General',3);
INSERT INTO faqs (question,answer,category,order_num) VALUES ('Will changing my website hurt my Google rankings?','We keep your page addresses and content structure and add SEO improvements, which protects your existing rankings. No one can guarantee rankings, but we take care not to break what already works.','General',4);
INSERT INTO faqs (question,answer,category,order_num) VALUES ('Do you work with UK businesses from outside the UK?','Yes. We work UK hours and communicate by WhatsApp, email and video call. Your site is built to UK standards, including UK GDPR and PECR cookie compliance.','General',5);
INSERT INTO faqs (question,answer,category,order_num) VALUES ('How do payments work?','50% deposit to start and the balance when you''re happy. You can pay by bank transfer or card.','General',6);
INSERT INTO faqs (question,answer,category,order_num) VALUES ('Can I update the website myself?','Yes. On WordPress and Elementor builds you can edit text, images and prices, and we give you a short training video.','General',7);
INSERT INTO faqs (question,answer,category,order_num) VALUES ('What if I don''t like the result?','You get 7 days of free revisions after launch so it is exactly right.','General',8);

